insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('18e9290e-07b6-4103-a903-7679831461cf', 'N2', 'N ＋ を問わず', 'Bất kể... (không phân biệt điều kiện đã nêu)', NULL, 'N ＋ を問わず', 'Diễn tả 1 điều gì đó đúng/áp dụng bất kể yếu tố đã nêu là gì', NULL, NULL, NULL, '{}', NULL, 69, 'N ＋ を問わず', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('6755fbb1-44c4-44bb-b870-1ae634760c88', 'N2', 'N ＋ をはじめ(として)／をはじめとするN', 'Điều đầu tiên kể đến là.../Đặc biệt là... (nêu ví dụ tiêu biểu nhất trong 1 nhóm)', NULL, 'N ＋ をはじめ(として)／をはじめとするN', 'Nêu 1 ví dụ tiêu biểu, đại diện nhất trong số nhiều đối tượng cùng loại', NULL, NULL, NULL, '{}', NULL, 69, 'N ＋ をはじめ(として)／をはじめとするN', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('92c545af-1742-4128-8ed8-3af5c11e343a', 'N2', 'N ＋ をめぐって／をめぐり／をめぐるN', 'Xoay xung quanh... (vấn đề/tranh chấp xoay quanh 1 chủ đề)', NULL, 'N ＋ をめぐって／をめぐり／をめぐるN', 'Diễn tả 1 cuộc tranh luận/tranh chấp/thảo luận xoay quanh 1 chủ đề cụ thể', NULL, NULL, NULL, '{}', NULL, 69, 'N ＋ をめぐって／をめぐり／をめぐるN', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('44e0ac30-a71f-4730-81d7-48c6bbdf60db', 'N2', 'N ＋ のもとで', 'Dưới/Dựa vào/Nhờ vào... (dưới sự chỉ dạy/điều kiện/ảnh hưởng của ai đó)', NULL, 'N ＋ のもとで', 'Diễn tả 1 hành động được thực hiện dưới sự chỉ dạy/quản lý/điều kiện của ai đó', NULL, NULL, NULL, '{}', NULL, 69, 'N ＋ のもとで', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('53858b9e-5169-420b-a71f-1ad9bddbf571', 'N2', 'N／普通形(Aな／Nである) ＋ のみならず', 'Không chỉ...mà còn/mà ngay cả... (mở rộng phạm vi mạnh hơn cả も)', NULL, 'N／普通形(Aな／Nである) ＋ のみならず', 'Nhấn mạnh mở rộng phạm vi ra ngoài đối tượng đã nêu, mang tính trang trọng', NULL, NULL, NULL, '{}', NULL, 69, 'N／普通形(Aな／Nである) ＋ のみならず', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('f0f43bca-7f3f-4633-9e51-919dec3d424d', 'N2', 'N ＋ はもとより', 'N là đương nhiên, cũng.../Không chỉ...mà còn... (điều hiển nhiên đúng, mở rộng thêm)', NULL, 'N ＋ はもとより', 'Khẳng định 1 điều là đương nhiên đúng, sau đó mở rộng thêm ra 1 phạm vi khác', NULL, NULL, NULL, '{}', NULL, 69, 'N ＋ はもとより', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('bf22ebe3-fd1e-4164-b95f-c1b798f0bb66', 'N2', 'N ＋ はともかく(として)', 'Khoan bàn, nói đến.../Chưa cần quan tâm đến...mà... (tạm gác lại 1 yếu tố để nói yếu tố quan trọng hơn)', NULL, 'N ＋ はともかく(として)', 'Tạm gác lại 1 yếu tố để tập trung vào yếu tố quan trọng hơn ở vế sau', NULL, NULL, NULL, '{}', NULL, 69, 'N ＋ はともかく(として)', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('e3c71dbe-8a26-48ab-8681-bb63cb72040d', 'N2', 'N ＋ はさておき', 'Chưa nói đến, khoan nói đến, tạm bỏ qua một bên... (gác lại chủ đề để chuyển sang chủ đề chính)', NULL, 'N ＋ はさておき', 'Tạm gác lại 1 chủ đề đang nói để chuyển sang chủ đề quan trọng hơn', NULL, NULL, NULL, '{}', NULL, 69, 'N ＋ はさておき', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('0391104d-4763-4d77-bdfe-2a95c30c2175', 'N2', '普通形(Aな／Nである) ＋ からには／以上(は)／上は', 'Một khi mà đã.../Vì...nên đương nhiên là... (nêu tiền đề rồi khẳng định nghĩa vụ/quyết tâm tất yếu)', NULL, '普通形(Aな／Nである) ＋ からには／以上(は)／上は', 'Nêu 1 tiền đề/hoàn cảnh đã xác định, từ đó khẳng định nghĩa vụ/quyết tâm tất yếu phải có ở vế sau', NULL, NULL, NULL, '{}', NULL, 69, '普通形(Aな／Nである) ＋ からには／以上(は)／上は', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('851e21fc-b006-424b-b460-5004257e8e39', 'N2', 'N ＋ からいって／からいうと／からいえば', 'Xét từ phương diện...mà nói.../Xét về mặt...mà nói... (đưa ra nhận định dựa trên 1 tiêu chí cụ thể)', NULL, 'N ＋ からいって／からいうと／からいえば', 'Đưa ra nhận định/đánh giá dựa trên 1 tiêu chí/góc nhìn cụ thể đã nêu', NULL, NULL, NULL, '{}', NULL, 69, 'N ＋ からいって／からいうと／からいえば', 'pdf', 'ok')
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('18e9290e-07b6-4103-a903-7679831461cf', NULL, 1, 'standard', 'インターネットがあれば場所を問わずに、仕事ができる。', 'Nếu mà có internet thì bất kì địa điểm nào cũng có thể làm việc được.', 'インターネットがあれば場所＿＿＿、仕事ができる。', 'を問わずに', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('18e9290e-07b6-4103-a903-7679831461cf', NULL, 2, 'daily', 'この仕事は年齢を問わず募集している。', 'Công việc này tuyển dụng bất kể độ tuổi.', 'この仕事は年齢＿＿＿募集している。', 'を問わず', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('18e9290e-07b6-4103-a903-7679831461cf', NULL, 3, 'daily', '昼夜を問わず、工事は続けられた。', 'Công trình được tiếp tục bất kể ngày đêm.', '昼夜＿＿＿、工事は続けられた。', 'を問わず', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('6755fbb1-44c4-44bb-b870-1ae634760c88', NULL, 1, 'standard', '彼は英語をはじめ、中国語やフランス語など5か国語を話せる。', 'Anh ấy có thể nói 5 ngôn ngữ, đầu tiên phải kể đến là tiếng Anh, tiếng Trung và tiếng Pháp.', '彼は英語＿＿＿、中国語やフランス語など5か国語を話せる。', 'をはじめ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('6755fbb1-44c4-44bb-b870-1ae634760c88', NULL, 2, 'daily', '社長をはじめ、社員全員がこのプロジェクトに参加した。', 'Tất cả nhân viên, đứng đầu là giám đốc, đều tham gia dự án này.', '社長＿＿＿、社員全員がこのプロジェクトに参加した。', 'をはじめ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('6755fbb1-44c4-44bb-b870-1ae634760c88', NULL, 3, 'daily', '日本をはじめとするアジア諸国で人気がある。', 'Được ưa chuộng ở các nước châu Á, đặc biệt là Nhật Bản.', '日本＿＿＿アジア諸国で人気がある。', 'をはじめとする', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('92c545af-1742-4128-8ed8-3af5c11e343a', NULL, 1, 'standard', '祖父の遺産をめぐって、父とおじは対立している。', 'Bố tôi và bác đối đầu nhau xoay quanh vấn đề tài sản của ông để lại.', '祖父の遺産＿＿＿、父とおじは対立している。', 'をめぐって', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('92c545af-1742-4128-8ed8-3af5c11e343a', NULL, 2, 'daily', 'その計画をめぐり、住民の間で議論が続いている。', 'Cuộc tranh luận giữa người dân vẫn đang tiếp diễn xoay quanh kế hoạch đó.', 'その計画＿＿＿、住民の間で議論が続いている。', 'をめぐり', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('92c545af-1742-4128-8ed8-3af5c11e343a', NULL, 3, 'daily', '環境問題をめぐる会議が開かれた。', 'Cuộc họp xoay quanh vấn đề môi trường đã được tổ chức.', '環境問題＿＿＿会議が開かれた。', 'をめぐる', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('44e0ac30-a71f-4730-81d7-48c6bbdf60db', NULL, 1, 'standard', '弟は有名な建築家のもとで3年間修行を積んだ。', 'Em trai tôi đã rèn luyện trong suốt 3 năm dưới sự chỉ dạy của một kiến trúc sư nổi tiếng.', '弟は有名な建築家＿＿＿3年間修行を積んだ。', 'のもとで', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('44e0ac30-a71f-4730-81d7-48c6bbdf60db', NULL, 2, 'daily', '彼女は厳しい先生のもとで、ピアノを習っている。', 'Cô ấy đang học đàn piano dưới sự dạy dỗ của một giáo viên nghiêm khắc.', '彼女は厳しい先生＿＿＿、ピアノを習っている。', 'のもとで', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('44e0ac30-a71f-4730-81d7-48c6bbdf60db', NULL, 3, 'daily', '同じ条件のもとで実験を行った。', 'Thí nghiệm đã được tiến hành dưới cùng 1 điều kiện.', '同じ条件＿＿＿実験を行った。', 'のもとで', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('53858b9e-5169-420b-a71f-1ad9bddbf571', NULL, 1, 'standard', 'この商品は安いのみならず質もいいので、多くの人に購入されている。', 'Sản phẩm này không chỉ rẻ mà chất lượng rất tốt nên được nhiều người mua.', 'この商品は安い＿＿＿質もいいので、多くの人に購入されている。', 'のみならず', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('53858b9e-5169-420b-a71f-1ad9bddbf571', NULL, 2, 'daily', '彼は日本語のみならず、韓国語も話せる。', 'Anh ấy không chỉ nói được tiếng Nhật mà còn cả tiếng Hàn.', '彼は日本語＿＿＿、韓国語も話せる。', 'のみならず', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('53858b9e-5169-420b-a71f-1ad9bddbf571', NULL, 3, 'daily', 'この病気は子供のみならず、大人にも見られる。', 'Căn bệnh này không chỉ thấy ở trẻ em mà còn cả người lớn.', 'この病気は子供＿＿＿、大人にも見られる。', 'のみならず', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f0f43bca-7f3f-4633-9e51-919dec3d424d', NULL, 1, 'standard', '大学院に進学することは、父はもとより母も賛成だ。', 'Về việc tôi học tiếp lên cao học, bố tôi đương nhiên đồng ý, mẹ tôi cũng vậy.', '大学院に進学することは、父＿＿＿母も賛成だ。', 'はもとより', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f0f43bca-7f3f-4633-9e51-919dec3d424d', NULL, 2, 'daily', 'この店は味はもとより、雰囲気も素晴らしい。', 'Quán này hương vị đương nhiên ngon, không khí cũng rất tuyệt.', 'この店は味＿＿＿、雰囲気も素晴らしい。', 'はもとより', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f0f43bca-7f3f-4633-9e51-919dec3d424d', NULL, 3, 'daily', '彼は仕事はもとより、家事も完璧にこなす。', 'Anh ấy công việc đương nhiên giỏi, việc nhà cũng làm hoàn hảo.', '彼は仕事＿＿＿、家事も完璧にこなす。', 'はもとより', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bf22ebe3-fd1e-4164-b95f-c1b798f0bb66', NULL, 1, 'standard', 'あの店の料理は見た目はともかく、値段が安く味がいいと評判だ。', 'Đồ ăn của quán kia khoan hãy bàn đến hình thức, trước tiên nó được đánh giá là giá rẻ và rất ngon.', 'あの店の料理は見た目＿＿＿、値段が安く味がいいと評判だ。', 'はともかく', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bf22ebe3-fd1e-4164-b95f-c1b798f0bb66', NULL, 2, 'daily', '結果はともかく、努力したことに意味がある。', 'Khoan bàn đến kết quả, việc đã nỗ lực là có ý nghĩa.', '結果＿＿＿、努力したことに意味がある。', 'はともかく', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bf22ebe3-fd1e-4164-b95f-c1b798f0bb66', NULL, 3, 'daily', '値段はともかくとして、性能はとてもいい。', 'Chưa cần quan tâm đến giá cả, hiệu năng thì rất tốt.', '値段＿＿＿、性能はとてもいい。', 'はともかくとして', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e3c71dbe-8a26-48ab-8681-bb63cb72040d', NULL, 1, 'standard', '事件のきっかけはさておき、けが人がいなくて本当によかった。', 'Khoan hãy bàn đến nguyên nhân của sự việc đó, thật là may vì không có ai bị thương cả.', '事件のきっかけ＿＿＿、けが人がいなくて本当によかった。', 'はさておき', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e3c71dbe-8a26-48ab-8681-bb63cb72040d', NULL, 2, 'daily', '冗談はさておき、本題に入りましょう。', 'Chuyện đùa tạm gác lại, chúng ta vào việc chính thôi.', '冗談＿＿＿、本題に入りましょう。', 'はさておき', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e3c71dbe-8a26-48ab-8681-bb63cb72040d', NULL, 3, 'daily', '値段の話はさておき、まずデザインを見てください。', 'Chuyện giá cả tạm gác lại, trước tiên hãy xem thiết kế đã.', '値段の話＿＿＿、まずデザインを見てください。', 'はさておき', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0391104d-4763-4d77-bdfe-2a95c30c2175', NULL, 1, 'standard', '会社の社長であるからには、従業員に尊敬される存在でいなくてはならないと思う。', 'Một khi đã là giám đốc của công ty, tôi cho rằng cần phải là người được nhân viên tôn trọng.', '会社の社長である＿＿＿、従業員に尊敬される存在でいなくてはならないと思う。', 'からには', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0391104d-4763-4d77-bdfe-2a95c30c2175', NULL, 2, 'daily', '引き受けた以上は、最後まで責任を持ってやる。', 'Một khi đã nhận việc rồi thì phải có trách nhiệm làm đến cùng.', '引き受けた＿＿＿、最後まで責任を持ってやる。', '以上は', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0391104d-4763-4d77-bdfe-2a95c30c2175', NULL, 3, 'daily', '日本に住む上は、日本語を勉強すべきだ。', 'Một khi đã sống ở Nhật thì nên học tiếng Nhật.', '日本に住む＿＿＿、日本語を勉強すべきだ。', '上は', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('851e21fc-b006-424b-b460-5004257e8e39', NULL, 1, 'standard', '見た目からいうと、山田さんよりも田中さんの方がお金持ちであると思う。', 'Xét từ vẻ bề ngoài, tôi nghĩ anh Tanaka giàu hơn anh Yamada.', '見た目＿＿＿、山田さんよりも田中さんの方がお金持ちであると思う。', 'からいうと', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('851e21fc-b006-424b-b460-5004257e8e39', NULL, 2, 'daily', '経験からいって、この方法はうまくいかないだろう。', 'Xét từ kinh nghiệm mà nói, cách này chắc sẽ không thành công.', '経験＿＿＿、この方法はうまくいかないだろう。', 'からいって', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('851e21fc-b006-424b-b460-5004257e8e39', NULL, 3, 'daily', '値段からいえば、こちらの方がお得だ。', 'Xét về giá cả mà nói, cái này lợi hơn.', '値段＿＿＿、こちらの方がお得だ。', 'からいえば', 'generated');
