insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('851e21fc-b006-424b-b460-5004257e8e39', NULL, 'choose_meaning', 'Mẫu ngữ pháp "N ＋ からいって／からいうと／からいえば" (usage này) có nghĩa là gì?', 'Khoan bàn, nói đến.../Chưa cần quan tâm đến...mà... (tạm gác lại 1 yếu tố để nói yếu tố quan trọng hơn)', 'Chưa nói đến, khoan nói đến, tạm bỏ qua một bên... (gác lại chủ đề để chuyển sang chủ đề chính)', 'N là đương nhiên, cũng.../Không chỉ...mà còn... (điều hiển nhiên đúng, mở rộng thêm)', 'Xét từ phương diện...mà nói.../Xét về mặt...mà nói... (đưa ra nhận định dựa trên 1 tiêu chí cụ thể)', 'Xét từ phương diện...mà nói.../Xét về mặt...mà nói... (đưa ra nhận định dựa trên 1 tiêu chí cụ thể)', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('851e21fc-b006-424b-b460-5004257e8e39', NULL, 'choose_connection', 'Cách nối nào tạo ra nghĩa: "Xét từ phương diện...mà nói.../Xét về mặt...mà nói... (đưa ra nhận định dựa trên 1 tiêu chí cụ thể)"?', 'N ＋ からいって／からいうと／からいえば', 'N ＋ をはじめ(として)／をはじめとするN', 'N ＋ はさておき', 'N／普通形(Aな／Nである) ＋ のみならず', 'N ＋ からいって／からいうと／からいえば', 'generated');
